"use client";
import Link from "next/link";
import { LucideIcon, ArrowRight } from "lucide-react";
import { motion } from "framer-motion";

interface CardProps {
  title: string;
  description: string;
  href: string;
  icon: LucideIcon;
  color: "blue" | "orange" | "purple" | "pink" | "emerald" | "sky" | "amber";
}

const colorStyles = {
  blue: {
    iconBg: "bg-[#63D2F3] shadow-[0_5px_0_0_#48BBDB]",
    hoverBorder: "hover:border-[#63D2F3]/30",
    accent: "bg-[#63D2F3]",
    glow: "shadow-[#63D2F3]/20"
  },
  orange: {
    iconBg: "bg-[#F6AD55] shadow-[0_5px_0_0_#DD6B20]",
    hoverBorder: "hover:border-[#F6AD55]/30",
    accent: "bg-[#F6AD55]",
    glow: "shadow-[#F6AD55]/20"
  },
  purple: {
    iconBg: "bg-[#D6BCFA] shadow-[0_5px_0_0_#9F7AEA]",
    hoverBorder: "hover:border-[#D6BCFA]/30",
    accent: "bg-[#D6BCFA]",
    glow: "shadow-[#D6BCFA]/20"
  },
  pink: {
    iconBg: "bg-[#FED7E2] dark:bg-[#F687B3] shadow-[0_5px_0_0_#F687B3] dark:shadow-[0_5px_0_0_#B83280]",
    hoverBorder: "hover:border-[#FED7E2]/30 dark:hover:border-[#F687B3]/30",
    accent: "bg-[#F687B3]",
    glow: "shadow-[#F687B3]/20"
  },
  // Mapping helpers
  emerald: { iconBg: "bg-[#10B981] shadow-[0_5px_0_0_#059669]", hoverBorder: "hover:border-[#10B981]/30", accent: "bg-[#10B981]", glow: "shadow-[#10B981]/20" },
  sky: { iconBg: "bg-[#0EA5E9] shadow-[0_5px_0_0_#0284C7]", hoverBorder: "hover:border-[#0EA5E9]/30", accent: "bg-[#0EA5E9]", glow: "shadow-[#0EA5E9]/20" },
  amber: { iconBg: "bg-[#F59E0B] shadow-[0_5px_0_0_#D97706]", hoverBorder: "hover:border-[#F59E0B]/30", accent: "bg-[#F59E0B]", glow: "shadow-[#F59E0B]/20" }
};

export default function DashboardCard({ title, description, href, icon: Icon, color }: CardProps) {
  const style = colorStyles[color] || colorStyles.blue;

  return (
    <Link href={href} className="group block h-full outline-none">
      <div className={`
        relative h-full bg-white dark:bg-slate-900 border-2 border-slate-50 dark:border-slate-800 p-8 rounded-[3rem] 
        transition-all duration-500 ease-[cubic-bezier(0.23,1,0.32,1)]
        hover:shadow-[0_30px_60px_rgba(0,0,0,0.06)] dark:hover:shadow-[0_30px_60px_rgba(0,0,0,0.4)]
        hover:-translate-y-2
        ${style.hoverBorder}
      `}>
        
        {/* 1. Icon Container */}
        <div className={`
          relative w-16 h-16 rounded-[1.5rem] flex items-center justify-center mb-10 
          ${style.iconBg} text-white transition-all duration-500 z-10
          group-hover:rotate-[-8deg] group-hover:scale-110
        `}>
          <Icon size={30} strokeWidth={2.5} />
        </div>

        {/* 2. Text Content */}
        <div className="space-y-3 relative z-10">
          <h3 className="text-2xl font-black text-slate-800 dark:text-white tracking-tighter transition-colors group-hover:text-slate-900 dark:group-hover:text-[#63D2F3]">
            {title}
          </h3>
          <p className="text-sm font-bold text-slate-400 dark:text-slate-500 leading-relaxed group-hover:text-slate-500 dark:group-hover:text-slate-400 transition-colors">
            {description}
          </p>
        </div>

        {/* 3. Footer / CTA */}
        <div className="mt-10 flex items-center justify-between relative z-10">
            <div className="flex items-center gap-3">
                <div className={`w-2.5 h-2.5 rounded-full ${style.accent} shadow-lg ${style.glow} animate-pulse`} />
                <span className="text-[10px] font-black uppercase tracking-[0.25em] text-slate-400 dark:text-slate-600 group-hover:text-slate-900 dark:group-hover:text-slate-300 transition-all">
                    Launch Module
                </span>
            </div>
            
            <div className={`
                w-10 h-10 rounded-2xl flex items-center justify-center bg-slate-50 dark:bg-slate-800/50 
                text-slate-400 dark:text-slate-600 border border-transparent
                group-hover:bg-slate-900 dark:group-hover:bg-white group-hover:text-white dark:group-hover:text-slate-900 
                group-hover:rotate-[-45deg] transition-all duration-500
            `}>
                <ArrowRight size={20} strokeWidth={3} />
            </div>
        </div>

        {/* 4. Large Background Decorative Icon */}
        <div className="absolute top-8 right-8 text-slate-100 dark:text-slate-800/30 opacity-40 dark:opacity-20 group-hover:opacity-100 group-hover:text-[#63D2F3]/10 dark:group-hover:text-[#63D2F3]/5 transition-all duration-700 group-hover:scale-125 group-hover:rotate-12 pointer-events-none">
          <Icon size={120} strokeWidth={1.5} />
        </div>

        {/* Bottom Inner Glow Effect */}
        <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-slate-50/50 dark:from-slate-800/10 to-transparent rounded-b-[3rem] pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
      </div>
    </Link>
  );
}

"use client";

import {
  Bell,
  Menu,
  Search,
  User,
  ChevronDown,
  Sparkles,
  Zap,
  Moon,
  Sun,
  X,
} from "lucide-react";
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Link from "next/link";
import { useDashboardTheme } from "../../../components/ThemeProvider";

export default function DashboardHeader({
  onOpenSidebar,
}: {
  onOpenSidebar: () => void;
}) {
  const [open, setOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const { theme, toggleTheme } = useDashboardTheme();

  const notifications = [
    {
      title: "Courses",
      text: "New React module is live",
      time: "2m ago",
      color: "text-[#63D2F3]",
    },
    {
      title: "System",
      text: "Login detected from Chrome",
      time: "1h ago",
      color: "text-[#F6AD55]",
    },
  ];

  return (
    <header className="px-4 md:px-6 py-4 sticky top-0 z-[100] bg-[#F8FAFC] dark:bg-zinc-950 transition-colors duration-500">
      <div
        className="max-w-7xl mx-auto flex items-center justify-between bg-white dark:bg-zinc-900 border-2 border-slate-50 dark:border-zinc-800 rounded-3xl md:rounded-[2.5rem] px-4 py-2.5 md:px-5 md:py-3 shadow-[0_8px_30px_rgb(0,0,0,0.04)] relative"
      >
        {/* LEFT: Logo + Mobile Menu */}
        <div className="flex items-center gap-3 md:gap-4">
          <button
            onClick={onOpenSidebar}
            className="lg:hidden p-2.5 rounded-xl bg-slate-50 dark:bg-zinc-800 text-slate-600 dark:text-zinc-300 hover:bg-[#63D2F3] hover:text-white transition-all"
          >
            <Menu size={20} strokeWidth={3} />
          </button>

          <div className="flex items-center gap-2.5">
            <div className="w-9 h-9 md:w-10 md:h-10 bg-[#63D2F3] rounded-xl md:rounded-2xl flex items-center justify-center shadow-[0_4px_0_0_#48BBDB] transform -rotate-3">
              <Sparkles size={18} className="text-white" fill="white" />
            </div>
            <div className="hidden xs:flex flex-col">
              <span className="text-lg md:text-xl font-black tracking-tighter leading-none text-slate-800 dark:text-white">
                Jnexia
              </span>
              <span className="text-[9px] md:text-[10px] font-black text-[#63D2F3] uppercase tracking-[0.2em]">
                Active
              </span>
            </div>
          </div>
        </div>

        {/* CENTER: Search (Hidden on Mobile unless toggled) */}
        <div className="hidden md:flex flex-1 max-w-md mx-8">
          <div className="w-full flex items-center rounded-2xl px-5 py-2.5 bg-slate-50 dark:bg-zinc-800 border-2 border-transparent focus-within:border-[#63D2F3] transition-all shadow-inner">
            <Search size={18} className="text-slate-400" strokeWidth={3} />
            <input
              type="text"
              placeholder="Quick Search..."
              className="bg-transparent border-none outline-none text-sm ml-3 w-full text-slate-700 dark:text-zinc-200 font-bold placeholder:text-slate-300"
            />
          </div>
        </div>

        {/* RIGHT: Actions */}
        <div className="flex items-center gap-2 md:gap-3">
          
          {/* Mobile Search Toggle */}
          <button 
            onClick={() => setSearchOpen(!searchOpen)}
            className="md:hidden p-3 rounded-xl bg-slate-50 dark:bg-zinc-800 text-slate-400 dark:text-zinc-300"
          >
            <Search size={20} strokeWidth={3} />
          </button>

          {/* Theme Toggle */}
          <button
            onClick={toggleTheme}
            className="p-3 rounded-xl md:rounded-2xl border-2 bg-white dark:bg-zinc-800 border-slate-50 dark:border-zinc-700 text-slate-500 dark:text-zinc-300 hover:text-[#63D2F3] transition-all"
          >
            {theme === "dark" ? <Sun size={20} strokeWidth={3} /> : <Moon size={20} strokeWidth={3} />}
          </button>

          {/* NOTIFICATIONS */}
          <div className="relative">
            <button
              onClick={() => setOpen(!open)}
              className={`p-3 rounded-xl md:rounded-2xl relative transition-all border-2 ${
                open
                  ? "bg-[#F6AD55] border-[#DD6B20] text-white shadow-lg"
                  : "bg-white dark:bg-zinc-800 text-slate-400 dark:text-zinc-300 border-slate-50 dark:border-zinc-700 hover:text-[#F6AD55]"
              }`}
            >
              <Bell size={20} strokeWidth={3} />
              {!open && notifications.length > 0 && (
                <span className="absolute top-2 right-2 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white dark:border-zinc-800 animate-pulse" />
              )}
            </button>

            {/* RESPONSIVE DROPDOWN */}
            <AnimatePresence>
              {open && (
                <>
                  {/* Mobile Overlay Backdrop */}
                  <motion.div 
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    onClick={() => setOpen(false)}
                    className="fixed inset-0 bg-slate-900/20 backdrop-blur-sm z-40 lg:hidden"
                  />
                  
                  <motion.div
                    initial={{ opacity: 0, y: 15, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 10, scale: 0.95 }}
                    className="fixed left-4 right-4 md:absolute md:left-auto md:right-0 mt-4 md:w-80 z-50 bg-white dark:bg-zinc-900 border-2 border-slate-100 dark:border-zinc-800 rounded-[2rem] p-5 shadow-2xl"
                  >
                    <div className="flex items-center justify-between mb-4 px-1">
                      <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                        Notifications
                      </h3>
                      <button onClick={() => setOpen(false)} className="md:hidden p-1">
                        <X size={16} className="text-slate-400" />
                      </button>
                    </div>

                    <div className="space-y-2.5">
                      {notifications.map((note, i) => (
                        <div
                          key={i}
                          className="p-4 rounded-2xl bg-slate-50 dark:bg-zinc-800/50 border border-transparent hover:border-[#F6AD55]/20 transition-all"
                        >
                          <div className="flex justify-between mb-1">
                            <span className={`text-[9px] font-black uppercase ${note.color}`}>
                              {note.title}
                            </span>
                            <span className="text-[9px] font-bold text-slate-300 dark:text-zinc-600">
                              {note.time}
                            </span>
                          </div>
                          <p className="text-xs font-bold text-slate-700 dark:text-zinc-200">
                            {note.text}
                          </p>
                        </div>
                      ))}
                    </div>
                  </motion.div>
                </>
              )}
            </AnimatePresence>
          </div>

          {/* PROFILE */}
          <Link
            href="/dashboard/profile"
            className="hidden xs:flex items-center gap-2 pl-1.5 pr-3 py-1.5 rounded-xl bg-slate-50 dark:bg-zinc-800 border-2 border-transparent hover:border-slate-100 dark:hover:border-zinc-700 transition-all"
          >
            <div className="w-8 h-8 rounded-lg bg-white dark:bg-zinc-900 border border-slate-100 dark:border-zinc-700 flex items-center justify-center text-slate-500">
              <User size={18} strokeWidth={3} />
            </div>
            <ChevronDown size={14} className="text-slate-400" strokeWidth={3} />
          </Link>
        </div>
      </div>

      {/* MOBILE SEARCH BAR (Toggled) */}
      <AnimatePresence>
        {searchOpen && (
          <motion.div 
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            className="md:hidden overflow-hidden pt-3"
          >
            <div className="flex items-center rounded-2xl px-4 py-3 bg-white dark:bg-zinc-900 border-2 border-[#63D2F3] shadow-lg">
              <Search size={18} className="text-[#63D2F3]" strokeWidth={3} />
              <input
                autoFocus
                type="text"
                placeholder="Search resources..."
                className="bg-transparent border-none outline-none text-sm ml-3 w-full text-slate-700 dark:text-zinc-200 font-bold"
              />
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}

"use client";

import { useEffect, useState } from "react";
import { User, Mail, ShieldCheck } from "lucide-react";

export default function ProfileForm() {
  const [profile, setProfile] = useState({
    name: "",
    email: "",
    goal: "Cloud Architecture",
    level: "intermediate",
  });

  useEffect(() => {
    // 🔥 Load data saved during login
    const name = localStorage.getItem("user_name");
    const email = localStorage.getItem("user_email");

    setProfile((prev) => ({
      ...prev,
      name: name || "Student",
      email: email || "student@jnexia.ai",
    }));
  }, []);

  const inputBase =
    "w-full bg-slate-50 dark:bg-zinc-800/50 rounded-2xl py-4 px-5 text-sm font-bold";

  return (
    <div className="max-w-2xl mx-auto p-6">
      <div className="bg-white dark:bg-zinc-950 p-10 rounded-[3rem] shadow-xl space-y-8">
        {/* Header */}
        <div className="flex items-center gap-4">
          <div className="w-14 h-14 bg-[#F687B3] rounded-2xl flex items-center justify-center text-white">
            <User size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black">My Profile</h2>
            <p className="text-xs text-slate-400 uppercase tracking-widest">
              Student Identity
            </p>
          </div>
        </div>

        {/* Name */}
        <div>
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
            Full Name
          </label>
          <input
            className={inputBase}
            value={profile.name}
            onChange={(e) =>
              setProfile({ ...profile, name: e.target.value })
            }
          />
        </div>

        {/* Email (Read-only) */}
        <div className="opacity-80">
          <div className="flex items-center justify-between">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
              System Email
            </label>
            <ShieldCheck size={14} className="text-emerald-500" />
          </div>
          <input
            className={`${inputBase} cursor-not-allowed`}
            value={profile.email}
            disabled
          />
        </div>

        {/* Save */}
        <button className="w-full h-14 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-2xl font-black uppercase tracking-[0.2em]">
          Save Changes
        </button>
      </div>
    </div>
  );
}

