"use client";

import React, { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  Brain, FileText, MessageCircle, LayoutDashboard,
  GraduationCap, X, LogOut, ChevronRight, User
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

interface SidebarProps {
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
}

export default function Sidebar({ isOpen, setIsOpen }: SidebarProps) {
  const pathname = usePathname();
  const router = useRouter();
  const [userName, setUserName] = useState("Student");

  useEffect(() => {
    const storedName = localStorage.getItem("user_name");
    if (storedName) setUserName(storedName);
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    router.push("/"); // Or your login path
  };

  const menuItems = [
    { name: "Dashboard", icon: LayoutDashboard, path: "/dashboard", activeColor: "bg-[#63D2F3]" },
    { name: "Learning Path", icon: Brain, path: "/dashboard/learning-path", activeColor: "bg-[#F6AD55]" },
    { name: "Resume Analyzer", icon: FileText, path: "/dashboard/resume-analyzer", activeColor: "bg-[#4299E1]" },
    { name: "AI Chatbot", icon: MessageCircle, path: "/dashboard/chatbot", activeColor: "bg-[#B794F4]" },
    { name: "My Profile", icon: User, path: "/dashboard/profile", activeColor: "bg-[#F687B3]" },
  ];

  return (
    <>
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setIsOpen(false)}
            className="fixed inset-0 z-[150] lg:hidden bg-slate-900/40 backdrop-blur-sm"
          />
        )}
      </AnimatePresence>

      <aside className={`fixed lg:sticky top-0 left-0 h-screen z-[200] w-72 bg-white dark:bg-zinc-950 border-r-2 border-slate-50 dark:border-zinc-800 transition-transform ${isOpen ? "translate-x-0" : "-translate-x-full lg:translate-x-0"}`}>
        <div className="flex flex-col h-full">
          <div className="p-8 flex items-center justify-between shrink-0">
            <Link href="/dashboard" className="flex items-center gap-3">
              <div className="w-11 h-11 bg-[#63D2F3] rounded-2xl flex items-center justify-center shadow-[0_5px_0_0_#48BBDB]">
                <GraduationCap className="text-white w-7 h-7" />
              </div>
              <span className="text-2xl font-black tracking-tighter text-slate-800 dark:text-white uppercase">Jnexia</span>
            </Link>
          </div>

          <nav className="flex-1 px-4 space-y-2 overflow-y-auto">
            <p className="text-[10px] font-black uppercase tracking-[0.3em] px-4 mb-4 text-slate-300 dark:text-zinc-500">Main Menu</p>
            {menuItems.map((item) => {
              const isActive = pathname === item.path;
              return (
                <Link key={item.path} href={item.path} onClick={() => setIsOpen(false)}>
                  <div className={`flex items-center gap-3 px-4 py-3.5 rounded-[1.25rem] transition-all ${isActive ? `${item.activeColor} text-white` : "text-slate-500 hover:bg-slate-50 dark:hover:bg-zinc-900"}`}>
                    <item.icon size={20} className={isActive ? "text-white" : "text-slate-400"} strokeWidth={isActive ? 3 : 2} />
                    <span className={`text-sm ${isActive ? "font-black" : "font-bold"}`}>{item.name}</span>
                  </div>
                </Link>
              );
            })}
          </nav>

          <div className="p-6 space-y-3 shrink-0">
            <div className="px-4 py-4 bg-slate-50 dark:bg-zinc-900 rounded-[2rem] border-2 border-slate-100 dark:border-zinc-800 flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-[#F687B3] flex items-center justify-center text-white font-black text-sm">
                {userName.charAt(0).toUpperCase()}
              </div>
              <div className="min-w-0">
                <p className="text-xs font-black text-slate-800 dark:text-white truncate uppercase">{userName}</p>
                <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Student</p>
              </div>
            </div>

            <button onClick={handleLogout} className="w-full flex items-center gap-3 px-6 py-4 rounded-2xl text-slate-400 hover:text-red-500 transition-all font-black text-[10px] uppercase tracking-widest">
              <LogOut size={18} strokeWidth={3} />
              <span>Sign Out</span>
            </button>
          </div>
        </div>
      </aside>
    </>
  );
}

"use client";

import { useEffect, useState } from "react";
import {
  Brain,
  Sparkles,
  Map,
  ChevronRight,
  CheckCircle2,
  Zap,
  Rocket,
  AlertCircle,
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

const BASE_URL = "https://techxpression-hackathon.onrender.com/api";

export default function LearningPathPage() {
  const [goal, setGoal] = useState("");
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  /* ---------------------------
      GET existing learning path
  ---------------------------- */
  useEffect(() => {
    async function fetchLearningPath() {
      try {
        const token = localStorage.getItem("access_token");
        const res = await fetch(`${BASE_URL}/learning`, {
          headers: {
             "Authorization": `Bearer ${token}`
          }
        });
        
        if (!res.ok) return;

        const data = await res.json();
        // Check if data exists and is an array
        if (data?.path && Array.isArray(data.path)) {
          setResult(data.path);
        }
      } catch (err) {
        console.error("Failed to fetch learning path", err);
      }
    }

    fetchLearningPath();
  }, []);

  /* ---------------------------
      POST generate learning path
  ---------------------------- */
  async function generatePath() {
    if (!goal.trim()) return;

    setLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem("access_token");
      
      const res = await fetch(`${BASE_URL}/learning/generate`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}` // 🔥 Added Auth Token
        },
        body: JSON.stringify({
          topic: goal, 
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.message || "Failed to generate learning path");
      }

      // Ensure we set an array
      if (data.path && Array.isArray(data.path)) {
        setResult(data.path);
      } else {
         // Fallback if API returns a string or different format
         setResult(["Start basics of " + goal, "Deep dive into concepts", "Build a project"]);
      }
      
      setGoal(""); // Clear input on success
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="max-w-5xl mx-auto space-y-10 pb-20 px-4">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex items-center gap-2 mb-2"
          >
            <div className="p-1.5 bg-[#F6AD55]/10 rounded-lg text-[#F6AD55]">
              <Map size={16} strokeWidth={3} />
            </div>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">
              Strategy Engine
            </span>
          </motion.div>

          <h2 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white uppercase">
            AI Learning Path
          </h2>
          <p className="text-slate-500 font-bold text-sm mt-1">
            Personalized roadmap generated by our AI engine.
          </p>
        </div>
      </div>

      {/* Input Section */}
      <div className="bg-white dark:bg-zinc-950 p-8 rounded-[2.5rem] border-2 border-slate-100 dark:border-zinc-900 shadow-sm flex flex-col md:flex-row gap-4 items-end relative overflow-hidden">
        <div className="flex-1 w-full space-y-2 z-10">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">
            What do you want to learn?
          </label>

          <div className="relative">
            <Brain
              className="absolute left-5 top-1/2 -translate-y-1/2 text-[#F6AD55]"
              size={20}
            />
            <input
              className="w-full bg-slate-50 dark:bg-zinc-900 border-2 border-transparent focus:border-[#F6AD55] rounded-2xl py-4 pl-14 pr-5 text-sm font-bold outline-none transition-all dark:text-white"
              placeholder="e.g. Quantum Physics, React Development, Machine Learning"
              value={goal}
              onChange={(e) => setGoal(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && generatePath()}
            />
          </div>
        </div>

        <button
          onClick={generatePath}
          disabled={loading || !goal.trim()}
          className="bg-[#F6AD55] hover:bg-[#ed9a3d] text-white px-8 py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center gap-2 disabled:opacity-50 transition-all z-10 whitespace-nowrap"
        >
          {loading ? "Generating..." : "Create Roadmap"}
          <Sparkles size={16} className={loading ? "animate-spin" : ""} />
        </button>

        <Zap
          size={120}
          className="absolute -right-8 -bottom-8 opacity-[0.03] dark:opacity-[0.05] pointer-events-none"
        />
      </div>

      {/* Error Message */}
      <AnimatePresence>
        {error && (
          <motion.div 
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex items-center gap-2 justify-center p-4 bg-red-50 dark:bg-red-500/10 border border-red-100 dark:border-red-500/20 rounded-2xl text-red-600 text-xs font-bold"
          >
            <AlertCircle size={14} />
            {error}
          </motion.div>
        )}
      </AnimatePresence>

      {/* Results / Roadmap */}
      <AnimatePresence mode="wait">
        {result && (
          <motion.div 
            key="results"
            initial={{ opacity: 0, y: 20 }} 
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6"
          >
            <div className="flex items-center gap-4 mb-8">
               <div className="h-px flex-1 bg-slate-100 dark:bg-zinc-800" />
               <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Your Pathway</span>
               <div className="h-px flex-1 bg-slate-100 dark:bg-zinc-800" />
            </div>

            <div className="space-y-4 relative">
              {/* Vertical Line */}
              <div className="absolute left-[31px] top-0 bottom-0 w-1 bg-slate-100 dark:bg-zinc-800 rounded-full" />

              {result.map((step, index) => (
                <motion.div
                  key={index}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.1 }}
                  className="flex items-center gap-6 group"
                >
                  <div
                    className={`w-16 h-16 shrink-0 rounded-2xl flex items-center justify-center font-black text-xl z-10 transition-all
                    ${
                      index === 0
                        ? "bg-[#F6AD55] text-white shadow-lg shadow-orange-200 dark:shadow-none scale-110"
                        : "bg-white dark:bg-zinc-900 border-2 border-slate-100 dark:border-zinc-800 text-slate-400"
                    }`}
                  >
                    {index + 1}
                  </div>

                  <div className="flex-1 bg-white dark:bg-zinc-950 border-2 border-slate-100 dark:border-zinc-800 p-6 rounded-[2rem] flex justify-between items-center group-hover:border-[#F6AD55] transition-colors shadow-sm">
                    <div>
                      <p className="font-black text-slate-800 dark:text-white text-lg leading-tight">{step}</p>
                      {index === 0 && (
                        <div className="flex items-center gap-1 mt-2">
                          <CheckCircle2 size={12} className="text-[#F6AD55]" />
                          <span className="text-[9px] font-black text-[#F6AD55] uppercase tracking-tighter">
                            Current Focus
                          </span>
                        </div>
                      )}
                    </div>

                    <div className="p-2 rounded-xl bg-slate-50 dark:bg-zinc-900 text-slate-300 group-hover:text-[#F6AD55] transition-colors">
                      <ChevronRight size={20} strokeWidth={3} />
                    </div>
                  </div>
                </motion.div>
              ))}
            </div>

            <div className="flex justify-center pt-12">
              <motion.button 
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                className="px-10 py-5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-[2rem] font-black text-[11px] uppercase tracking-[0.2em] flex items-center gap-3 shadow-xl"
              >
                <Rocket size={16} />
                Save Roadmap to Profile
              </motion.button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

import { useState } from "react";
import { FileText, Upload, ShieldCheck, AlertCircle, FileCheck, Sparkles, X, CheckCircle2 } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export default function ResumeAnalyzer() {
  const [file, setFile] = useState<File | null>(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [score, setScore] = useState<number | null>(null);

  const handleAnalyze = () => {
    if (!file) return;
    setAnalyzing(true);
    setTimeout(() => {
      setAnalyzing(false);
      setScore(84);
    }, 2500);
  };

  return (
    <div className="max-w-5xl mx-auto space-y-10 pb-20 transition-colors duration-500">
      {/* 1. Header */}
      <div>
        <motion.div 
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          className="flex items-center gap-2 mb-2"
        >
          <div className="p-1.5 bg-[#63D2F3]/10 rounded-lg text-[#63D2F3]">
            <ShieldCheck size={16} strokeWidth={3} />
          </div>
          <span className="text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em]">ATS Optimizer</span>
        </motion.div>
        <h2 className="text-4xl font-black text-slate-900 dark:text-white tracking-tighter">Resume Analyzer</h2>
        <p className="text-slate-500 dark:text-slate-400 font-bold text-sm mt-1">Get AI-powered insights to beat the recruitment filters.</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-5 gap-8">
        {/* 2. Upload Section */}
        <div className="lg:col-span-3 space-y-6">
          <div className={`
            relative bg-white dark:bg-slate-900/50 backdrop-blur-xl border-4 border-dashed rounded-[3rem] p-12 
            flex flex-col items-center justify-center text-center transition-all duration-300
            ${file 
              ? 'border-[#63D2F3] bg-[#63D2F3]/5 dark:bg-[#63D2F3]/5' 
              : 'border-slate-100 dark:border-slate-800 hover:border-[#63D2F3]/30 dark:hover:border-[#63D2F3]/20 hover:bg-slate-50/50 dark:hover:bg-slate-800/30'}
          `}>
            
            {/* Animated Background Pulse for "Scanning" state */}
            {analyzing && (
              <motion.div 
                initial={{ opacity: 0 }}
                animate={{ opacity: [0.1, 0.3, 0.1] }}
                transition={{ duration: 1.5, repeat: Infinity }}
                className="absolute inset-0 bg-[#63D2F3] rounded-[2.8rem]"
              />
            )}

            <motion.div 
              animate={file ? { rotate: [0, 5, -5, 0] } : {}}
              className={`
                w-20 h-20 rounded-3xl flex items-center justify-center mb-6 z-10 transition-all duration-500
                ${file 
                  ? 'bg-[#63D2F3] text-white shadow-[0_8px_0_0_#48BBDB]' 
                  : 'bg-slate-50 dark:bg-slate-800 text-slate-300 dark:text-slate-600'}
              `}
            >
              {file ? <FileCheck size={32} strokeWidth={3} /> : <Upload size={32} strokeWidth={3} />}
            </motion.div>
            
            <div className="relative z-10">
              {file ? (
                <div className="space-y-3">
                  <p className="text-xl font-black text-slate-800 dark:text-white tracking-tight">{file.name}</p>
                  <button 
                    onClick={() => setFile(null)} 
                    className="flex items-center gap-2 mx-auto px-4 py-2 bg-white dark:bg-slate-800 border-2 border-slate-100 dark:border-slate-700 rounded-xl text-[10px] font-black uppercase tracking-widest text-rose-500 hover:border-rose-200 dark:hover:border-rose-900 transition-all shadow-sm"
                  >
                    <X size={14} strokeWidth={3} />
                    Change File
                  </button>
                </div>
              ) : (
                <div className="space-y-2">
                  <p className="text-xl font-black text-slate-800 dark:text-white tracking-tight">Drop your resume</p>
                  <p className="text-sm font-bold text-slate-400 dark:text-slate-500 mb-6">PDF or Word docs supported</p>
                  <label className="cursor-pointer inline-block px-8 py-3 bg-slate-900 dark:bg-[#63D2F3] hover:bg-[#63D2F3] dark:hover:bg-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] text-white dark:text-slate-900 transition-all shadow-xl active:translate-y-1 active:shadow-none">
                    Browse Files
                    <input type="file" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} />
                  </label>
                </div>
              )}
            </div>
          </div>

          <button 
            onClick={handleAnalyze}
            disabled={!file || analyzing}
            className="group w-full bg-[#63D2F3] text-white py-5 rounded-3xl font-black text-sm uppercase tracking-widest shadow-[0_8px_0_0_#48BBDB] hover:translate-y-[2px] hover:shadow-[0_6px_0_0_#48BBDB] active:translate-y-[8px] active:shadow-none transition-all flex items-center justify-center gap-3 disabled:opacity-50 disabled:bg-slate-100 dark:disabled:bg-slate-800 disabled:text-slate-400 disabled:shadow-none"
          >
            {analyzing ? (
              <>
                <div className="w-5 h-5 border-4 border-white/30 border-t-white rounded-full animate-spin" />
                <span>Running Neural Scan...</span>
              </>
            ) : (
              <>
                <span>Analyze Resume</span>
                <Sparkles size={20} className="fill-current transition-transform group-hover:rotate-12" />
              </>
